import java.util.Scanner;

public class BlackboardQuery {
    static final int MAX_QUERIES = 420;
    static int queryCount = 0;
    static Scanner sc = new Scanner(System.in);

    static int query(int r1, int c1, int r2, int c2) {
        if (queryCount >= MAX_QUERIES) {
            System.out.println("0");
            System.out.flush();
            System.exit(0);
        }
        System.out.println("? " + r1 + " " + c1 + " " + r2 + " " + c2);
        System.out.flush();
        queryCount++;
        return sc.nextInt();
    }

    public static void main(String[] args) {
        int N = sc.nextInt();
        int[] topRow = new int[N + 1];
        int[] bottomRow = new int[N + 1];
        boolean topDone = false, bottomDone = false;

        // Find first used cell in each row using binary search
        int lo = 1, hi = N;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (query(1, 1, 1, mid) > 0) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        if (query(1, lo, 1, lo) == 1) {
            topRow[lo] = 1;
        } else {
            topDone = true;
        }

        lo = 1; hi = N;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (query(2, 1, 2, mid) > 0) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        if (query(2, lo, 2, lo) == 1) {
            bottomRow[lo] = 1;
        } else {
            bottomDone = true;
        }

        // Fill rest by scanning
        for (int i = 1; i <= N; i++) {
            if (!topDone && topRow[i] == 0) {
                topRow[i] = query(1, i, 1, i);
            }
            if (!bottomDone && bottomRow[i] == 0) {
                bottomRow[i] = query(2, i, 2, i);
            }
            // If both rows fully known, stop early
            if (i == N || (topDone && bottomDone)) break;
        }

        // Output result
        System.out.print("! ");
        for (int i = 1; i <= N; i++) System.out.print(topRow[i]);
        System.out.print(" ");
        for (int i = 1; i <= N; i++) System.out.print(bottomRow[i]);
        System.out.println();
        System.out.flush();
    }
}

